def total_in_stock(items):
    total = 0
    for item in items:
        if item["in_stock"]:
            total += item["price"]
    return total

def get_max_price(items):
    max_price = 0
    for item in items:
        if item["price"] > max_price:
            max_price = item["price"]
    return max_price

