def count_positive(numbers):
    count = 0
    for number in numbers:
        if number > 0:
            count += 1
    return count

def average(numbers):
    total = count = 0
    for number in numbers:
        total += number
        count += 1
    if count == 0:
        return None
    return total / count

def filter_above(numbers, threshold):
    result = []
    for number in numbers:
        if number > threshold:
            result.append(number)
    return result

print(count_positive([3, -1, 0, 7, -2, 5]))
print(average([10, 20, 30]))
print(filter_above([1, 5, 3, 8, 2], 4))
print(average([]))

